```javascript
const defaults = { version: 1, theme: 'light' };

function readSettings() {
  try {
    const value = JSON.parse(localStorage.getItem('settings'));
    const valid = value?.version === 1 && ['light', 'dark'].includes(value.theme);
    return valid ? value : defaults;
  } catch {
    return defaults;
  }
}
```
